import type { FormulaFunction } from '../../core/types';
import { collectNumbers } from '../../core/args';
import { isError } from '../../core/errors';
import { mean } from '../../helpers/moments';

/**
 * AVERAGEA(value1, ...): the mean of all values; inside arrays text counts as 0 and
 * booleans as 1 or 0. #DIV/0! when there are no values.
 */
const AVERAGEA: FormulaFunction = {
  minArgs: 1,
  maxArgs: Infinity,
  call(args) {
    const numbers = collectNumbers(args, { rangeValues: 'all' });
    if (isError(numbers)) return numbers;
    return mean(numbers);
  },
};

export default AVERAGEA;

ops.oldString:
  /** Empty arguments (e.g. SUM(1,,2)): 'zero' (default) counts them as 0, 'ignore' skips them. */
  directEmpty?: 'zero' | 'ignore';
}

ops.newString:
  /** Empty arguments (e.g. SUM(1,,2)): 'zero' (default) counts them as 0, 'ignore' skips them. */
  directEmpty?: 'zero' | 'ignore';
  /**
   * Values inside arrays/ranges: 'numbers' (default) counts only numbers; 'all' also counts
   * text as 0 and booleans as 1 / 0, as the A-functions (AVERAGEA, ...) do.
   */
  rangeValues?: 'numbers' | 'all';
}

if (typeof cell === 'number') out.push(cell);
else if (rangeValues === 'all' && typeof cell === 'boolean') out.push(cell ? 1 : 0);
else if (rangeValues === 'all' && typeof cell === 'string') out.push(0);

